  "ch7_s9_b4": [
    {
      "type": "text",
      "pages": [
        {
          "text": "你在最後一排找到一張空椅，椅背貼著一張紙。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "作者席",
          "speaker": "",
          "effects": []
        },
        {
          "text": "你坐下的瞬間，舞台上的時間停止，所有角色都等待你決定下一幕，面前浮現一支筆，只要拿起來，你便能修改結局，黎靖站在舞台邊緣。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「你要寫嗎？」",
          "speaker": "黎靖",
          "effects": []
        },
        {
          "text": "「如果我不寫，故事會一直重複。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「如果你寫了，他們就得照你的內容活。」",
          "speaker": "黎靖",
          "effects": []
        },
        {
          "text": "未命名角色也看向你。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「至少可以寫一個沒有人死的版本。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「那仍然是你替他決定。」",
          "speaker": "黎靖",
          "effects": []
        },
        {
          "text": "筆停在你面前，你可以救下所有人，也可以讓黑色植物消失，但無論寫下什麼，你都會取代蘇璟辰成為新的作者。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "解鎖特殊選項：「成為作者」",
          "speaker": "SYSTEM",
          "effects": [
            "system"
          ]
        },
        {
          "text": "True Ending必要理解：「善意改寫仍然可能是控制」",
          "speaker": "SYSTEM",
          "effects": [
            "glitch",
            "system"
          ]
        }
      ]
    },
    {
      "type": "effects",
      "items": [
        {
          "kind": "flag",
          "name": "解鎖特殊選項：「成為作者」"
        }
      ]
    },
    {
      "type": "jump",
      "target": "ch7_s10"
    }
  ],
