  "ch9_s14": [
    {
      "type": "section",
      "title": "缺失的分鏡"
    },
    {
      "type": "text",
      "pages": [
        {
          "text": "黑色植物退到原稿邊緣後，最後一頁終於顯現，那不是結局，畫面裡，未命名角色與城市居民拆掉所有選項，站在空白街道中央，他們已經獲得離開分鏡的權利，卻不知道接下來要往哪裡走。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "右下角留著一格尚未完成的分鏡，鉛筆只畫出道路輪廓，遠處似乎有一扇門，也可能只是一塊沒有描完的建築陰影，對白框內完全空白，蘇璟辰坐在桌前，你坐到他身旁，沒有拿起畫筆，黎靖則站在另一側，將鉛筆放到蘇璟辰手邊。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「你要畫嗎？」他問。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「不知道。」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "「那就先看。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "三個人長時間沒有說話，第十三冊多次浮現催促提示。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "【請完成最後一格。】【請選擇故事結局。】【請確認正式版本。】",
          "speaker": "",
          "effects": []
        },
        {
          "text": "沒有人回應，那些提示最後自行變淡，房間裡只剩紙張、鉛筆與窗外逐漸移動的夕陽。",
          "speaker": "",
          "effects": []
        }
      ]
    },
    {
      "type": "jump",
      "target": "ch9_s15"
    }
  ],
