  "ch10_s4_b2": [
    {
      "type": "text",
      "pages": [
        {
          "text": "你進入廚房準備簡單的早餐。黎靖先嗅過每一份食物，最後選擇吃你的部分；蘇璟辰則盯著放在自己面前的盤子。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「你知道我們不會餓？」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "「知道。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「還準備？」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "「日常不一定只為了活下去。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "蘇璟辰拿起餐具吃了一口。黎靖立刻抬頭觀察他的反應。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「味道怎麼樣？」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「像有人第一次寫日常。」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "「很難吃？」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「不確定。可以再試一次。」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "- 蘇璟辰好感度＋5%",
          "speaker": "SYSTEM",
          "effects": [
            "system"
          ]
        },
        {
          "text": "- 黎靖好感度＋3%",
          "speaker": "SYSTEM",
          "effects": [
            "system"
          ]
        }
      ]
    },
    {
      "type": "jump",
      "target": "ch10_s5"
    }
  ],
  "ch10_s4_b3": [
    {
      "type": "text",
      "pages": [
        {
          "text": "你只準備自己的早餐。黎靖盯著盤子看了一會兒，蘇璟辰則若無其事地翻動原稿。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「你們不是不需要吃？」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "「確實。」",
          "speaker": "蘇璟辰",
          "effects": []
        },
        {
          "text": "「但我想吃。」",
          "speaker": "黎靖",
          "effects": []
        },
        {
          "text": "「那你先問。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "黎靖沉默幾秒，尾巴在桌面掃了一下。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "「可以分我嗎？」",
          "speaker": "黎靖",
          "effects": []
        },
        {
          "text": "「可以。」",
          "speaker": "你",
          "effects": []
        },
        {
          "text": "牠得到一小份早餐。蘇璟辰抬眼看著你們，唇角短暫揚了一下。",
          "speaker": "",
          "effects": []
        },
        {
          "text": "- 黎靖好感度＋5%",
          "speaker": "SYSTEM",
          "effects": [
            "system"
          ]
        },
        {
          "text": "- 蘇璟辰好感度＋1%",
          "speaker": "SYSTEM",
          "effects": [
            "system"
          ]
        }
      ]
    },
    {
      "type": "jump",
      "target": "ch10_s5"
    }
  ],
